function checkPasswordStrength(password) {
  if (password.length < 8) return 'weak';
  var hasUpper = /[A-Z]/.test(password);
  var hasLower = /[a-z]/.test(password);
  var hasDigit = /[0-9]/.test(password);
  var hasSpecial = /[^A-Za-z0-9]/.test(password);
  if (password.length >= 12 && hasUpper && hasLower && hasDigit && hasSpecial) return 'strong';
  return 'medium';
}

function createToken(payload, secret) {
  var data = JSON.stringify(payload);
  var encoded = btoa(data);
  var signature = btoa(secret + encoded);
  return encoded + '.' + signature;
}
function verifyToken(token, secret) {
  var parts = token.split('.');
  if (parts.length !== 2) return null;
  var encoded = parts[0], signature = parts[1];
  var expectedSig = btoa(secret + encoded);
  if (signature !== expectedSig) return null;
  try { return JSON.parse(atob(encoded)); } catch(e) { return null; }
}

function createRateLimiter(maxRequests, windowMs) {
  var clients = {};
  return function isAllowed(clientId) {
    var now = Date.now();
    if (!clients[clientId] || now - clients[clientId].windowStart >= windowMs) {
      clients[clientId] = { count: 1, windowStart: now };
      return true;
    }
    clients[clientId].count++;
    return clients[clientId].count <= maxRequests;
  };
}
